class Solution {
    private int[] nums;
    private int difference;
    private Map<Integer,Integer> frequency=new HashMap<>();
    private int dfs(int index){
        if(index==nums.length)return 1;
        int ways=dfs(index+1),value=nums[index];
        if(frequency.getOrDefault(value-difference,0)==0){
            frequency.put(value,frequency.getOrDefault(value,0)+1);
            ways+=dfs(index+1);
            frequency.put(value,frequency.get(value)-1);
        }
        return ways;
    }
    public int beautifulSubsets(int[] input,int k){
        nums=input;
        difference=k;
        Arrays.sort(nums);
        frequency.clear();
        return dfs(0)-1;
    }
}

